// Owner-editable settings. Items pass through unchanged.
const cfg = {
  repo: 'Unifight-haifa/unifight',
  branch: 'main',
  news_dir: 'src/content/news',
  site: 'https://unifight-haifa.github.io/unifight',
  news_json: 'https://unifight-haifa.github.io/unifight/news.json',
  fb_page_id: 'REPLACE_PAGE_ID',
  ig_user_id: 'REPLACE_IG_USER_ID',
  social_langs: ['he', 'ru'],
  max_posts_per_day: 5,
  max_revisions: 3,
  deploy_checks: 16,
};
return $input.all().map(it => ({ json: { ...it.json, cfg }, binary: it.binary }));

// EXIF orientation -> rotation, so pixels stay upright after metadata is stripped.
function orientation(b) {
  if (b[0] !== 0xFF || b[1] !== 0xD8) return 1;
  let i = 2;
  while (i + 4 < b.length && b[i] === 0xFF) {
    const marker = b[i + 1], len = b.readUInt16BE(i + 2);
    if (marker === 0xDA) break;
    if (marker === 0xE1 && b.toString('latin1', i + 4, i + 10) === 'Exif\0\0') {
      const t = i + 10, le = b.toString('latin1', t, t + 2) === 'II';
      const u16 = o => le ? b.readUInt16LE(o) : b.readUInt16BE(o);
      const u32 = o => le ? b.readUInt32LE(o) : b.readUInt32BE(o);
      const ifd = t + u32(t + 4);
      for (let k = 0, n = u16(ifd); k < n; k++) {
        const e = ifd + 2 + k * 12;
        if (u16(e) === 0x0112) return u16(e + 8);
      }
      return 1;
    }
    i += 2 + len;
  }
  return 1;
}
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const it = $input.all()[i];
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const rotate = { 3: 180, 6: 90, 8: 270 }[orientation(buf)] || 0;
  out.push({ json: { ...it.json, rotate }, binary: it.binary });
}
return out;

// Drop EXIF/XMP/IPTC/comment segments (GPS lives there), keep JFIF and ICC; one item with base64 files.
function segments(b) {
  if (b[0] !== 0xFF || b[1] !== 0xD8) throw new Error('Resized image is not a JPEG');
  const segs = []; let i = 2;
  while (i + 4 <= b.length) {
    while (b[i] === 0xFF && b[i + 1] === 0xFF) i++;
    if (b[i] !== 0xFF) throw new Error('Broken JPEG segment');
    const m = b[i + 1];
    if (m === 0xDA) { segs.push({ m, s: i, e: b.length }); break; }
    const e = i + 2 + b.readUInt16BE(i + 2);
    segs.push({ m, s: i, e }); i = e;
  }
  return segs;
}
const META = (m) => m === 0xE1 || m === 0xED || m === 0xFE || (m >= 0xE3 && m <= 0xEF);
function strip(b) {
  const keep = segments(b).filter(x => !META(x.m)).map(x => b.subarray(x.s, x.e));
  const out = Buffer.concat([b.subarray(0, 2), ...keep]);
  if (segments(out).some(x => META(x.m))) throw new Error('Metadata still present after strip');
  return out;
}
const items = $input.all();
const files = [];
for (let i = 0; i < items.length; i++) {
  const buf = strip(await this.helpers.getBinaryDataBuffer(i, 'data'));
  files.push({ path: i === 0 ? 'cover.jpg' : `photo-${i + 1}.jpg`, b64: buf.toString('base64'), bytes: buf.length });
}
const { cfg, rotate, index, ...meta } = items[0].json;
return [{ json: { ...meta, files } }];

const pub = $('Get Publisher').first().json;
const d = $('Pack Images').first().json;
const cfg = $('Config').first().json.cfg;
// Build fails on an unknown author, so refuse before translating.
const authorOk = $input.first().json.statusCode === 200;
const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Jerusalem' });
const count = pub.posts_day === today ? Number(pub.posts_count || 0) : 0;
const ok = authorOk && count < cfg.max_posts_per_day;
return [{ json: {
  ok, today, posts_count: count,
  src_lang: d.src_lang, title: d.title, body: d.body, cover_alt: d.cover_alt,
  corrections: '', previous: null, revision: 0,
  channel: d.channel, chat_id: d.chat_id, email: d.email,
  notify_admin: !authorOk,
  notify: ok ? '' : !authorOk ? `Тренер «${d.author_id}» не найден в content/coaches на сайте, новость не принята. Администратор получил сообщение.`
    : `Лимит: не больше ${cfg.max_posts_per_day} новостей в день. Попробуйте завтра.`,
  audit: { actor_id: d.author_id, action: authorOk ? 'rate_limited' : 'unknown_author', target: d.draft_id, result: 'denied', detail: String(count) },
} }];

// Validate the translation and flag what the author must check.
let st; try { st = $('Decision').last().json; } catch (e) { st = null; }
if (!st || st.decision !== 'edit') st = $('Rate Check').first().json;
const d = $('Pack Images').first().json;
const r = $input.first().json;
const raw = typeof r.content === 'string' ? r.content
  : (r.content?.[0]?.text ?? r.text ?? r.output ?? r.message?.content ?? JSON.stringify(r));
const m = String(raw).match(/\{[\s\S]*\}/);
if (!m) throw new Error('Translation reply is not JSON');
const t = JSON.parse(m[0]);
const L = ['he', 'ru', 'en'];
for (const l of L) {
  for (const k of ['title', 'summary', 'body']) {
    if (!t[l] || typeof t[l][k] !== 'string' || !t[l][k].trim()) throw new Error(`Translation missing ${l}.${k}`);
  }
  if (t[l].summary.length > 160) t[l].summary = t[l].summary.slice(0, 157).replace(/\s+\S*$/, '') + '…';
  t[l].cover_alt = (t[l].cover_alt || d.cover_alt || t[l].title).slice(0, 200);
}
if (!st.corrections) { t[d.src_lang].title = d.title; t[d.src_lang].body = d.body; }
const warnings = [];
const src = t[d.src_lang].title + ' ' + t[d.src_lang].body;
const nums = [...new Set(src.match(/\d+(?:[.,:]\d+)*/g) || [])];
for (const l of L) {
  const txt = t[l].title + ' ' + t[l].body;
  const miss = nums.filter(n => !txt.includes(n));
  if (miss.length) warnings.push(`${l.toUpperCase()}: нет чисел ${miss.join(', ')}`);
}
if (/נבחרת|нивхерет|nivheret/i.test(src) && !/ישראל|Израил|Israel/i.test(src)) {
  if (!/נבחרת/.test(t.he.body + t.he.title)) warnings.push('HE: нет слова «נבחרת»');
  if (!/нивхерет/i.test(t.ru.body + t.ru.title)) warnings.push('RU: нет «сборная клуба (нивхерет)»');
  if (!/nivheret/i.test(t.en.body + t.en.title)) warnings.push('EN: нет "selected team (nivheret)"');
  if (/national team/i.test(t.en.body + t.en.title) || /сборн\S* (Израиля|страны)|национальн\S* сборн/i.test(t.ru.body + t.ru.title)) {
    warnings.push('Нивхерет переведена как национальная сборная — исправьте');
  }
}
let slug = String(t.slug || '').toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);
if (slug.length < 3) slug = 'news';
const date = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Jerusalem' });
return [{ json: {
  tr: { he: t.he, ru: t.ru, en: t.en }, slug, date, folder: `${date}-${slug}`, warnings,
  revision: st.revision || 0, channel: d.channel, chat_id: d.chat_id, email: d.email,
  draft: { draft_id: d.draft_id, folder: '', author_id: d.author_id, channel: d.channel, status: 'preview',
           title_en: t.en.title, commit_sha: '', fb_post_id: '', ig_media_id: '', error: '' },
} }];

// One Telegram message per language (4096-char limit per message).
const p = $('Parse Translation').last().json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return ['he', 'ru', 'en'].map(l => ({ json: {
  chat_id: p.chat_id,
  text: `<b>${l.toUpperCase()}</b>\n<b>${esc(p.tr[l].title)}</b>\n<i>${esc(p.tr[l].summary)}</i>\n\n${esc(p.tr[l].body)}`.slice(0, 4000),
} }));

// Map the form answer; a timeout or anything unclear counts as cancel.
const r = $input.first().json;
const d = r.data ?? r;
const pick = String(d['Решение'] ?? '');
const corrections = String(d['Правки'] ?? '').trim();
const p = $('Parse Translation').last().json;
const base = $('Rate Check').first().json;
const cfg = $('Config').first().json.cfg;
let decision = /Опубликовать/.test(pick) ? 'publish' : /Исправить/.test(pick) ? 'edit' : 'cancel';
let reason = decision === 'cancel' ? (pick ? 'Отменено автором.' : 'Нет ответа 48 часов, черновик отменён.') : '';
if (decision === 'edit' && p.revision >= cfg.max_revisions) {
  decision = 'cancel'; reason = `Больше ${cfg.max_revisions} правок — отменено. Отправьте новость заново.`;
}
return [{ json: {
  ...base, decision, corrections, previous: p.tr, revision: p.revision + 1,
  notify: reason,
} }];

const p = $('Parse Translation').last().json;
const d = $('Decision').last().json;
return [{ json: {
  channel: p.channel, chat_id: p.chat_id, email: p.email, notify: d.notify,
  draft: { ...p.draft, status: 'cancelled' },
  audit: { actor_id: p.draft.author_id, action: 'cancel', target: p.draft.draft_id, result: 'ok', detail: d.notify },
} }];

// Build the post folder: three Markdown files plus images.
const p = $('Parse Translation').last().json;
const d = $('Pack Images').first().json;
const cfg = $('Config').first().json.cfg;
// URL is /<lang>/news/<slug>/, so the slug (folder minus date) must be unique across all posts.
const res = $input.first().json;
if (res.statusCode !== 200 && res.statusCode !== 404) throw new Error(`Listing news folder failed: ${res.statusCode}`);
const taken = new Set((Array.isArray(res.body) ? res.body : []).map(x => x.name.replace(/^\d{4}-\d{2}-\d{2}-/, '')));
let slug = p.slug;
for (let n = 2; taken.has(slug); n++) slug = `${p.slug}-${n}`;
const folder = `${p.date}-${slug}`;
// Author text can't form tags, links or images: escape \ first, then [ ] ( (no literal "](" for the source check) and < >.
const mdText = v => String(v).replace(/\\/g, '\\\\').replace(/[[\]()]/g, c => '\\' + c)
  .replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Frontmatter is plain text; \u escapes keep the value exact with no literal < > [ ] in the file.
const yq = v => JSON.stringify(String(v)).replace(/[<>[\]]/g, c => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));
const tags = (d.tags || []).map(String);
const alt = p.tr.en.title.replace(/[[\]\\<>()]/g, '');
const extra = d.files.slice(1).map(f => `\n\n![${alt}](${f.path})`).join('');
const md = ['he', 'ru', 'en'].map(l => ({
  path: `${cfg.news_dir}/${folder}/index.${l}.md`,
  content: ['---',
    `title: ${yq(p.tr[l].title)}`, `summary: ${yq(p.tr[l].summary)}`, `date: ${p.date}`,
    `author: ${yq(d.author_id)}`, 'cover: "cover.jpg"', `cover_alt: ${yq(p.tr[l].cover_alt)}`,
    `tags: [${tags.map(yq).join(', ')}]`, 'draft: false', '---', '',
  ].join('\n') + '\n' + mdText(p.tr[l].body.trim()) + extra + '\n',
}));
return [{ json: { folder, slug, md, tr: p.tr, tags } }];

const f = $('Final Files').first().json;
const cfg = $('Config').first().json.cfg;
return $('Pack Images').first().json.files.map(x => ({ json: { path: `${cfg.news_dir}/${f.folder}/${x.path}`, b64: x.b64 } }));

const f = $('Final Files').first().json;
const paths = $('Blob Items').all().map(i => i.json.path);
const shas = $input.all().map(i => i.json.sha);
if (shas.length !== paths.length || shas.some(s => !s)) throw new Error('Blob upload failed');
return [{ json: {
  base_tree: $('Get Head Commit').first().json.tree.sha,
  tree: [
    ...f.md.map(m => ({ path: m.path, mode: '100644', type: 'blob', content: m.content })),
    ...paths.map((path, k) => ({ path, mode: '100644', type: 'blob', sha: shas[k] })),
  ],
} }];

const p = $('Parse Translation').last().json;
const f = $('Final Files').first().json;
const sha = $input.first().json.object?.sha || $('Create Commit').first().json.sha;
return [{ json: {
  channel: p.channel, chat_id: p.chat_id, email: p.email,
  notify: `Новость сохранена (${f.folder}). Сайт обновится через 1–2 минуты, потом опубликую в Facebook и Instagram.`,
  draft: { ...p.draft, folder: f.folder, status: 'committed', commit_sha: sha },
  audit: { actor_id: p.draft.author_id, action: 'commit', target: f.folder, result: 'ok', detail: sha },
} }];

// Look for the post in news.json; $runIndex counts loop passes.
const cfg = $('Config').first().json.cfg;
const slug = $('Final Files').first().json.slug;
// HTTP Request splits a top-level JSON array into one item per post.
const post = $input.all().map(i => i.json).find(x => x && x.slug === slug);
const attempt = $runIndex + 1;
return [{ json: { state: post ? 'live' : attempt >= cfg.deploy_checks ? 'timeout' : 'retry', post: post || null, attempt } }];

const p = $('Parse Translation').last().json;
const f = $('Final Files').first().json;
return [{ json: {
  channel: p.channel, chat_id: p.chat_id, email: p.email, notify_admin: true,
  notify: `Новость ${f.folder} сохранена, но за 12 минут не появилась на сайте. Facebook и Instagram не тронуты. Проверьте сборку: https://github.com/Unifight-haifa/unifight/actions`,
  draft: { ...p.draft, folder: f.folder, status: 'deploy_timeout', commit_sha: $('Committed').first().json.draft.commit_sha },
  audit: { actor_id: p.draft.author_id, action: 'deploy_wait', target: f.folder, result: 'timeout', detail: '' },
} }];

const cfg = $('Config').first().json.cfg;
const f = $('Final Files').first().json;
const post = $json.post || {};
const url = l => post.url?.[l] || `${cfg.site}/${l}/news/${f.slug}/`;
const block = l => `${f.tr[l].title}\n${f.tr[l].summary}\n${url(l)}`;
const tags = f.tags.map(t => '#' + t.replace(/[\s#]+/g, '')).join(' ');
const ig = cfg.social_langs.map(l => `${f.tr[l].title}\n${f.tr[l].summary}`).join('\n\n')
  + `\n\n${url(cfg.social_langs[0])}` + (tags ? `\n\n${tags}` : '');
return [{ json: {
  urls: { he: url('he'), ru: url('ru'), en: url('en') },
  fb_message: cfg.social_langs.map(block).join('\n\n'),
  fb_link: url(cfg.social_langs[0]),
  ig_caption: ig.slice(0, 2200),
  ig_image: post.cover || '',
  ig_alt: f.tr.en.cover_alt,
  // Title + link only: the link preview shows the summary, and Telegram caps a message at 4096 chars.
  wa: Object.fromEntries(['he', 'ru', 'en'].map(l => [l, 'https://wa.me/?text=' + encodeURIComponent(`${f.tr[l].title}\n${url(l)}`)])),
} }];

const p = $('Parse Translation').last().json;
const c = $('Committed').first().json;
const s = $('Build Social').first().json;
const get = n => { try { return $(n).first().json; } catch (e) { return {}; } };
const fb = get('FB Post'), ig = get('IG Publish'), igc = get('IG Container');
const err = o => o.error?.message || o.error || 'нет ответа';
const fbId = fb.id || '', igId = ig.id || '';
const problems = [];
if (!fbId) problems.push('Facebook: ' + err(fb));
if (!igId) problems.push('Instagram: ' + err(igc.error ? igc : ig));
const notify = [
  'Новость на сайте:', `HE ${s.urls.he}`, `RU ${s.urls.ru}`, `EN ${s.urls.en}`, '',
  `Facebook: ${fbId ? 'опубликовано' : 'не получилось'}`, `Instagram: ${igId ? 'опубликовано' : 'не получилось'}`,
  ...(problems.length ? ['', ...problems] : []), '',
  'WhatsApp — откройте ссылку и выберите группу родителей:',
  `HE ${s.wa.he}`, `RU ${s.wa.ru}`, `EN ${s.wa.en}`,
].join('\n');
return [{ json: {
  channel: p.channel, chat_id: p.chat_id, email: p.email, notify, notify_admin: problems.length > 0,
  draft: { ...c.draft, status: problems.length ? 'live_partial' : 'live', fb_post_id: fbId, ig_media_id: igId,
           error: problems.join('; ').slice(0, 500) },
  audit: { actor_id: p.draft.author_id, action: 'distribute', target: c.draft.folder,
           result: problems.length ? 'partial' : 'ok', detail: `fb=${fbId} ig=${igId}` },
} }];
